import json
P='../seas.json'; d={x['slug']:x for x in json.load(open(P))}
def up(slug, seafloor, cw, eco, hist, match, see):
    d[slug].update(seafloor=seafloor, climate_weather=cw, ecosystems=eco, history=hist, match=match, see=see)
C=["climate/ocean-heat","climate/coral-bleaching"]
up("mediterranean-sea","A complex basin of sub-basins (Alboran, Tyrrhenian, Ionian, Aegean, Levantine) with the Calypso Deep (~5,267 m) off Greece. About 5.6 million years ago it nearly dried out in the Messinian Salinity Crisis, leaving thick salt layers; the Zanclean flood through Gibraltar refilled it. Brine pools and mud volcanoes lie on its floor.","A hot, dry-summer 'Mediterranean climate'. It is warming ~20% faster than the global ocean, with repeated marine heatwaves since 2003 causing mass die-offs of gorgonians and the noble pen shell. 'Medicanes' (Mediterranean hurricane-like storms) such as Daniel in 2023 caused catastrophic floods in Libya.","Posidonia seagrass meadows, coralligenous reefs, red coral, submarine caves, deep cold-water corals, and over 1,000 non-native species that arrived through the Suez Canal (Lessepsian migration).","Cradle of Phoenician, Greek and Roman sea trade. Wrecks include the Antikythera wreck (with the Antikythera mechanism, the oldest known analogue computer) and Bronze Age ships like Uluburun. Jacques Cousteau pioneered scuba diving here.",["Mediterranean","E Atlantic; Mediterranean","NE Atlantic; Mediterranean","invasive Mediterranean"],["climate/ocean-heat","impacts/marine-protected-areas","seafloor/canyons-fjords-brine-pools","impacts/plastics-and-pollution"])
up("caribbean-sea","Floored by the Caribbean plate, with the Cayman Trough (~7,686 m) and the Mid-Cayman Rise, home to the deepest known black smokers (Beebe vent field, ~5,000 m). The Puerto Rico Trench lies just to the north.","The core of the Atlantic hurricane belt: warm water (>26.5°C) fuels storms from June to November. Sargassum influxes since 2011 smother beaches. Repeated heatwaves have bleached most reefs.","Coral reefs, the Mesoamerican Barrier Reef (second-largest reef system), mangroves, seagrass with manatees and turtles, and deep vents.","Columbus arrived in 1492; the Spanish treasure fleets and pirates of the 17th–18th centuries left many wrecks, including the San José galleon (found off Colombia in 2015).",["Caribbean","W Atlantic","Tropical worldwide","Florida"],C+["impacts/marine-protected-areas"])
up("gulf-of-mexico","Wide shelves around a deep central basin (Sigsbee Deep, ~4,384 m). Salt domes and cold seeps produce brine pools and methane hydrates; the Chicxulub crater from the dinosaur-killing asteroid lies under its southern rim.","The Loop Current feeds warm water that intensifies hurricanes (Katrina 2005, Harvey 2017, Ian 2022). Mississippi River nutrients create a summer 'dead zone' of hypoxic water averaging ~14,000 km².","Seagrass, oyster reefs, the Flower Garden Banks coral reefs, cold seeps with tubeworms and ice worms, and Kemp's ridley turtle nesting beaches.","The 2010 Deepwater Horizon spill released ~4.9 million barrels of oil, the largest marine spill in US history.",["Gulf of Mexico","W Atlantic"],["climate/deoxygenation","seafloor/canyons-fjords-brine-pools","seafloor/hydrothermal-vents"])
up("sargasso-sea","Overlies deep abyssal plains (Nares and Hatteras) and the Bermuda Rise; about 4,500–6,500 m deep.","Bounded only by currents of the North Atlantic Gyre, so it has calm, clear, nutrient-poor warm water. The Bermuda Atlantic Time-series Study (since 1988) records ocean warming and acidification here.","Floating sargassum mats host endemic sargassum fish, crabs and nudibranchs, and nurseries for sea turtles. It is the spawning ground of European and American eels.","Named by Portuguese sailors; Columbus feared his ships would be trapped in its weed. The 2014 Hamilton Declaration created a commission for its conservation.",["Sargasso","Sargasso Sea; Atlantic","W Atlantic"],["climate/acidification","impacts/plastics-and-pollution"])
up("north-sea","A shallow shelf sea (average ~95 m) that was dry land, Doggerland, until about 8,000 years ago; fishermen still trawl up mammoth bones and Stone Age tools. The Norwegian Trench reaches ~700 m.","Severe winter storms and storm surges (the 1953 flood killed over 2,000 people in the Netherlands and UK). Warming has shifted cod north and brought in warm-water species.","Sandbanks, oyster reefs (being restored), Wadden Sea mudflats (a UNESCO World Heritage site), seal colonies and seabird cliffs.","Viking routes, the Hanseatic League, the Battle of Jutland (1916) whose wrecks lie on the floor, North Sea oil since 1970 and now the world's largest offshore wind farms.",["NE Atlantic","N Atlantic","North Sea"],["impacts/bottom-trawling","climate/ocean-heat"])
up("baltic-sea","A young, shallow (average ~55 m) brackish sea left by the retreating ice sheet; the Landsort Deep reaches ~459 m. Land is still rising after the ice age.","Very low salinity (from ~2 PSU in the north to ~20 at the entrance) and limited exchange with the North Sea make it vulnerable. Its deep basins have one of the world's largest dead zones, caused by nutrient runoff.","A mix of marine and freshwater species, bladderwrack, grey and ringed seals, harbour porpoises, cod and herring.","The cold, low-salinity water lacks shipworms, so wrecks survive intact, from the Swedish warship Vasa (1628, raised in 1961) to medieval cogs.",["Baltic"],["climate/deoxygenation","impacts/plastics-and-pollution"])
up("black-sea","A deep basin (~2,212 m) linked to the Mediterranean only by the narrow Bosporus. Below ~150 m the water has no oxygen and is full of hydrogen sulfide, the largest anoxic water body on Earth.","Strong stratification: a fresher surface layer from rivers (Danube, Dnieper, Don) sits above dense salty water that never mixes.","Surface life includes dolphins, anchovy and turbot; the sulfidic depths hold only microbes. The invasive comb jelly Mnemiopsis collapsed fisheries in the 1980s.","Because there is no oxygen, wooden shipwrecks are perfectly preserved: the 2018 Black Sea MAP project found a Greek trading ship ~2,400 years old, the oldest intact shipwreck known.",["Black Sea","Caspian and Black seas"],["climate/deoxygenation"])
up("red-sea","A young ocean in the making, formed as Africa and Arabia split apart; the central rift reaches ~3,040 m and holds hot brine pools such as Atlantis II Deep.","Among the warmest and saltiest seas (~40 PSU) because of extreme evaporation and almost no rivers. Its northern corals are unusually heat-tolerant and may be a refuge as oceans warm.","Fringing coral reefs with high endemism, whale sharks, dugongs and Red Sea clownfish.","A trade route since antiquity; the Suez Canal (1869) connected it to the Mediterranean.",["Red Sea","Indian Ocean; Red Sea","Indo-Pacific; Red Sea"],["climate/coral-bleaching","seafloor/canyons-fjords-brine-pools"])
up("arabian-sea","Includes the Carlsberg Ridge and the Indus Fan, the second-largest submarine fan.","The southwest monsoon drives intense upwelling and plankton blooms. It holds one of the world's thickest oxygen minimum zones, and cyclones have become more frequent as it warms (e.g. Tauktae 2021 and Biparjoy 2023).","Upwelling-driven fisheries (oil sardine, mackerel), Lakshadweep atolls and the Gulf of Kutch coral reefs.","Ancient Harappan ports such as Lothal and Indo-Roman trade; Mumbai and Karachi are major ports.",["Arabian","N Indian Ocean","Indian Ocean","Indo-Pacific","Indo-W Pacific"],["climate/deoxygenation","climate/ocean-heat"])
up("bay-of-bengal","Floored by the Bengal Fan, the largest submarine fan on Earth, built from Himalayan sediment carried by the Ganges and Brahmaputra.","Huge river inflow makes the surface fresh and strongly stratified, keeping it warm and favouring intense cyclones. Its funnel shape and low coasts amplify storm surges (Bhola 1970, Odisha super cyclone 1999, Amphan 2020).","The Sundarbans mangroves, olive ridley mass-nesting in Odisha, hilsa runs, Irrawaddy dolphins and the Andaman reefs.","Chola kingdom naval expeditions; Kolkata, Chennai, Visakhapatnam and Chittagong are major ports.",["Bay of Bengal","N Indian Ocean","Sundarbans","Ganges","Indo-Pacific","Indo-W Pacific","South Asia","Indian Ocean"],["climate/ocean-heat","climate/deoxygenation"])
up("coral-sea","Holds the Great Barrier Reef on its western margin and deep basins over ~9,000 m in the New Hebrides Trench nearby.","Cyclone-prone in the austral summer; repeated mass bleaching since 1998 (2016, 2017, 2020, 2022, 2024).","The Great Barrier Reef, the world's largest reef system, with ~1,500 fish species, dugongs, nesting turtles and Osprey Reef sharks.","The 1942 Battle of the Coral Sea was the first naval battle fought entirely by aircraft carriers.",["Coral Sea","Australia","W Pacific","Indo-Pacific","Indo-W Pacific","Pacific"],["climate/coral-bleaching","impacts/marine-protected-areas"])
up("south-china-sea","Shelves in the north and south around a deep central basin (~5,500 m); the Spratly and Paracel reefs.","Typhoon-prone; driven by the East Asian monsoon.","Coral reefs at the edge of the Coral Triangle, seagrass, and some of the world's most heavily fished waters.","Maritime Silk Road trade; today about a third of global shipping passes through, and overlapping territorial claims make it a geopolitical flashpoint.",["South China Sea","W Pacific","Indo-Pacific","Indo-W Pacific","Pacific"],["climate/coral-bleaching","impacts/marine-protected-areas"])
up("sea-of-japan","A nearly enclosed back-arc basin (~3,742 m) whose straits are shallow, so it has its own deep water mass.","Cold winter monsoon winds form deep water locally; this formation has weakened with warming.","Snow crabs, firefly squid (Toyama Bay), Japanese flying squid and Pacific saury.","The 1905 Battle of Tsushima. The sea's name is disputed (Korea uses 'East Sea').",["Japan","NW Pacific","N Pacific","Pacific"],["ocean-system/deep-circulation"])
up("bering-sea","A broad shallow shelf in the east (the drowned Bering land bridge, Beringia) and a deep basin in the west.","Seasonal sea ice drives the ecosystem; the 2018–19 ice-free winters and heatwave triggered the collapse of the snow crab fishery.","Walrus, Steller sea lions, northern fur seals, seabirds in millions, and the pollock and king crab fisheries.","People crossed Beringia into the Americas; Vitus Bering explored it in 1728 and 1741.",["Bering","Alaska","N Pacific","Arctic"],["climate/ocean-heat"])
up("weddell-sea","Deep shelf and abyssal plain; the Filchner-Ronne Ice Shelf covers its southern part.","The main source of Antarctic Bottom Water. Its clockwise gyre traps thick sea ice.","Emperor penguin colonies, Weddell seals and, in 2021, a vast colony of ~60 million nesting icefish found on the seabed.","Shackleton's Endurance was crushed by its ice in 1915 and found at 3,008 m in 2022.",["Antarctic","Antarctica","Southern Ocean","Weddell"],["ocean-system/deep-circulation","exploration/history-of-exploration"])
up("ross-sea","Contains the Ross Ice Shelf, the largest floating ice shelf (about the size of France).","Polynyas produce sea ice and dense water; considered one of the least altered ocean ecosystems.","Antarctic toothfish, Adélie and emperor penguins, Ross Sea orcas and Weddell seals.","Ross discovered it in 1841. The Ross Sea MPA (2016) was the first large high-seas MPA, about 1.55 million km².",["Antarctic","Antarctica","Southern Ocean","Ross"],["impacts/marine-protected-areas"])
up("persian-gulf","Shallow (average ~35 m), formed as a foreland basin of the Zagros mountains; dry land during the last ice age.","Some of the hottest seawater on Earth (over 35°C in summer) and very salty; its corals tolerate heat that would kill others.","Corals, dugongs, seagrass and pearl oysters.","Pearl diving was the economic base of the Gulf for millennia before oil.",["Persian Gulf","Arabian","Indian Ocean"],["climate/coral-bleaching","climate/ocean-heat"])
up("tasman-sea","Deep (~5,943 m), with the Lord Howe Rise and seamount chains.","The East Australian Current is warming it rapidly, making it a marine heatwave hotspot.","Lord Howe Island's southernmost coral reef, kelp forests, and grey nurse sharks.","Named after Abel Tasman (1642).",["Australia","New Zealand","SW Pacific","Pacific"],["climate/ocean-heat"])
up("hudson-bay","A shallow inland sea (average ~100 m) still rising after the ice age (~1 cm a year).","Ice-covered most of the year; ice-free seasons lengthening, stressing polar bears.","Polar bears around Churchill, beluga whales in summer estuaries, and ringed seals.","Henry Hudson's 1610–11 expedition; the Hudson's Bay Company fur trade.",["Arctic","Hudson"],["climate/ocean-heat"])
up("barents-sea","A broad shelf sea (average ~230 m) warmed by Atlantic water.","Rapid 'Atlantification': sea ice retreating and Atlantic species moving in.","Among the largest cod stocks, capelin, and introduced red king crabs.","Willem Barentsz explored it in 1596; it was a WWII Arctic convoy route.",["Barents","Arctic","N Atlantic","Arctic; N Atlantic"],["climate/ocean-heat"])
up("caspian-sea","The largest enclosed inland body of water, in a basin below sea level; its deepest point is ~1,025 m.","Water level fluctuates with Volga inflow and is now falling due to evaporation and warming.","Beluga sturgeon and Caspian seals.","Major oil and gas region since the 19th century.",["Caspian"],["climate/ocean-heat"])
json.dump(list(d.values()),open(P,'w'),ensure_ascii=False,indent=0)
print("ok")
